174→function handleSSEEvent(
175→  eventType: string,
176→  data: Record<string, unknown>,
177→  callbacks: AgentCallbacks,
178→) {
179→  switch (eventType) {
180→    case 'thinking':
181→    case 'answer':
182→      callbacks.onTextChunk(data.text as string);
183→      break;
184→    case 'thinking_done':
185→      callbacks.onThinkingDone();
186→      break;
187→    case 'tool_call':
188→      callbacks.onToolCall({
189→        toolCallId: (data.id as string) ?? '',
190→        toolName: (data.name as string) ?? undefined,
191→        sql: (data.sql as string) ?? '',
192→        command: (data.command as string) ?? undefined,
193→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
194→        columns: [],
195→        rows: [],
196→        rowCount: 0,
197→      });
198→      break;
199→    case 'tool_result': {
200→      const result: ToolCallResult = {
201→        toolCallId: (data.id as string) ?? '',
202→        toolName: (data.name as string) ?? undefined,
203→        sql: (data.sql as string) ?? '',
204→        columns: (data.columns as string[]) ?? [],
205→        rows: (data.rows as Record<string, unknown>[]) ?? [],
206→        rowCount: (data.rowCount as number) ?? 0,
207→        error: (data.error as string) ?? undefined,
208→        output: (data.output as string) ?? undefined,
209→        rawContent: (data.content as string) ?? undefined,
210→        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
211→      };
212→      callbacks.onToolResult(result);
213→      break;
214→    }
215→    case 'subagent_start':
216→      callbacks.onSubagentStart?.({
217→        id: data.id as string,
218→        name: data.name as string,
219→        prompt: (data.prompt as string) ?? '',
220→      });
221→      break;
222→    case 'subagent_end':
223→      callbacks.onSubagentEnd?.({
224→        id: data.id as string,
225→        name: data.name as string,
226→        result: (data.result as string) ?? undefined,
227→        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
228→      });
229→      break;
230→    case 'done':
231→      callbacks.onDone((data.session_id as string) ?? null);
232→      break;
233→    case 'error':
234→      callbacks.onError((data.message as string) ?? 'Unknown error');
235→      break;
236→  }
237→}
