 11→/**
 12→ * Strip chart_spec JSON code blocks from answer text.
 13→ * The orchestrator may include the raw chart spec JSON even though the chart
 14→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 15→ * or Plotly trace data so they don't appear as raw text.
 16→ */
 17→function stripChartSpecBlocks(text: string): string {
 18→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
 19→}
