  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→
 12→function generateId() {
 13→  return crypto.randomUUID();
 14→}
 15→
 16→export function AgentProvider({
 17→  children,
 18→  refreshTables,
 19→}: {
 20→  children: ReactNode;
 21→  refreshTables: () => Promise<void>;
 22→}) {
 23→  const userSessionId = useSessionId();
 24→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 25→  const [isStreaming, setIsStreaming] = useState(false);
 26→  const abortRef = useRef<AbortController | null>(null);
 27→  const textBufferRef = useRef('');
 28→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 29→  const assistantIdRef = useRef('');
 30→  const segmentsRef = useRef<ContentSegment[]>([]);
 31→  const currentTextRef = useRef('');
 32→  const sessionIdRef = useRef<string | null>(null);
 33→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 34→
 35→  const flushText = useCallback(() => {
 36→    const text = textBufferRef.current;
 37→    if (!text) return;
 38→    const id = assistantIdRef.current;
 39→    currentTextRef.current += text;
 40→    setMessages((prev) =>
 41→      prev.map((m) =>
 42→        m.id === id ? { ...m, content: m.content + text } : m
 43→      )
 44→    );
 45→    textBufferRef.current = '';
 46→  }, []);
 47→
 48→  const sendMessage = useCallback(
 49→    async (text: string) => {
 50→      if (isStreaming) return;
 51→
 52→      const userMsg: ChatMessage = {
 53→        id: generateId(),
 54→        role: 'user',
 55→        content: text,
 56→      };
 57→
 58→      const assistantId = generateId();
 59→      assistantIdRef.current = assistantId;
 60→      const assistantMsg: ChatMessage = {
 61→        id: assistantId,
 62→        role: 'assistant',
 63→        content: '',
 64→        toolCalls: [],
 65→        isStreaming: true,
 66→      };
 67→
 68→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 69→      setIsStreaming(true);
 70→      textBufferRef.current = '';
 71→      segmentsRef.current = [];
 72→      currentTextRef.current = '';
 73→
 74→      // If there's pending history from a delete, start a new Langfuse session with that context
 75→      const pendingHistory = pendingHistoryRef.current;
 76→      pendingHistoryRef.current = null;
 77→      const langfuseSessionId = pendingHistory ? crypto.randomUUID() : null;
 78→
 79→      const controller = new AbortController();
 80→      abortRef.current = controller;
 81→
 82→      await runAgentLoop(
 83→        text,
 84→        sessionIdRef.current,
 85→        langfuseSessionId,
 86→        pendingHistory,
 87→        {
 88→          onTextChunk: (chunk) => {
 89→            textBufferRef.current += chunk;
 90→            if (!flushTimerRef.current) {
 91→              flushTimerRef.current = setTimeout(() => {
 92→                flushText();
 93→                flushTimerRef.current = null;
 94→              }, 50);
 95→            }
 96→          },
 97→          onThinkingDone: () => {
 98→            // Extended thinking just ended and a text block is starting.
 99→            // Create a thinking segment from accumulated thinking text.
100→            if (flushTimerRef.current) {
101→              clearTimeout(flushTimerRef.current);
102→              flushTimerRef.current = null;
103→            }
104→            flushText();
105→            if (currentTextRef.current.trim()) {
106→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
107→              currentTextRef.current = '';
108→            }
109→            setMessages((prev) =>
110→              prev.map((m) =>
111→                m.id === assistantId
112→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
113→                  : m
114→              )
115→            );
116→          },
117→          onToolCall: (pending: ToolCallResult) => {
118→            if (flushTimerRef.current) {
119→              clearTimeout(flushTimerRef.current);
120→              flushTimerRef.current = null;
121→            }
122→            flushText();
123→            if (currentTextRef.current.trim()) {
124→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
125→              currentTextRef.current = '';
126→            }
127→            // Add a pending tool segment so the input is shown immediately
128→            segmentsRef.current.push({
129→              type: 'tool',
130→              toolResult: pending,
131→            });
132→            setMessages((prev) =>
133→              prev.map((m) =>
134→                m.id === assistantId
135→                  ? { ...m, segments: [...segmentsRef.current] }
136→                  : m
137→              )
138→            );
139→          },
140→          onToolResult: (result: ToolCallResult) => {
141→            // Merge result into pending tool segment (keep input info, add output)
142→            const pendingIdx = segmentsRef.current.findIndex(
143→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
144→            );
145→            if (pendingIdx !== -1) {
146→              const pending = segmentsRef.current[pendingIdx].toolResult!;
147→              segmentsRef.current[pendingIdx] = {
148→                type: 'tool',
149→                toolResult: {
150→                  ...pending,
151→                  ...result,
152→                  sql: result.sql || pending.sql,
153→                  toolName: result.toolName || pending.toolName,
154→                  command: result.command || pending.command,
155→                  toolInput: result.toolInput || pending.toolInput,
156→                },
157→              };
158→            } else {
159→              segmentsRef.current.push({ type: 'tool', toolResult: result });
160→            }
161→            setMessages((prev) =>
162→              prev.map((m) =>
163→                m.id === assistantId
164→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
165→                  : m
166→              )
167→            );
168→            refreshTables();
169→          },
170→          onSubagentStart: (data) => {
171→            if (flushTimerRef.current) {
172→              clearTimeout(flushTimerRef.current);
173→              flushTimerRef.current = null;
174→            }
175→            flushText();
176→            if (currentTextRef.current.trim()) {
177→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
178→              currentTextRef.current = '';
179→            }
180→            segmentsRef.current.push({
181→              type: 'subagent_start',
182→              subagentId: data.id,
183→              subagentName: data.name,
184→              text: data.prompt,
185→            });
186→            setMessages((prev) =>
187→              prev.map((m) =>
188→                m.id === assistantId
189→                  ? { ...m, segments: [...segmentsRef.current] }
190→                  : m
191→              )
192→            );
193→          },
194→          onSubagentEnd: (data) => {
195→            segmentsRef.current.push({
196→              type: 'subagent_end',
197→              subagentId: data.id,
198→              subagentName: data.name,
199→              chart_spec: data.chart_spec,
200→              text: data.result,

200→              text: data.result,
201→            });
202→            setMessages((prev) =>
203→              prev.map((m) =>
204→                m.id === assistantId
205→                  ? { ...m, segments: [...segmentsRef.current] }
206→                  : m
207→              )
208→            );
209→          },
210→          onDone: (newSessionId) => {
211→            if (newSessionId) sessionIdRef.current = newSessionId;
212→            if (flushTimerRef.current) {
213→              clearTimeout(flushTimerRef.current);
214→              flushTimerRef.current = null;
215→            }
216→            flushText();
217→            if (currentTextRef.current.trim()) {
218→              segmentsRef.current.push({
219→                type: 'answer',
220→                text: currentTextRef.current,
221→              });
222→              currentTextRef.current = '';
223→            }
224→            setMessages((prev) =>
225→              prev.map((m) =>
226→                m.id === assistantId
227→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
228→                  : m
229→              )
230→            );
231→            setIsStreaming(false);
232→            abortRef.current = null;
233→          },
234→          onError: (error) => {
235→            if (flushTimerRef.current) {
236→              clearTimeout(flushTimerRef.current);
237→              flushTimerRef.current = null;
238→            }
239→            flushText();
240→            setMessages((prev) =>
241→              prev.map((m) =>
242→                m.id === assistantId
243→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
244→                  : m
245→              )
246→            );
247→            setIsStreaming(false);
248→            abortRef.current = null;
249→          },
250→        },
251→        controller.signal,
252→        userSessionId,
253→      );
254→    },
255→    [isStreaming, flushText, refreshTables, userSessionId]
256→  );
257→
258→  const editMessage = useCallback(
259→    async (messageIndex: number, newContent: string) => {
260→      if (isStreaming) return;
261→
262→      // Build conversation history from messages before the edit point
263→      const conversationHistory: { role: string; content: string }[] = [];
264→      for (let i = 0; i < messageIndex; i++) {
265→        const msg = messages[i];
266→        if (msg.role === 'user' || msg.role === 'assistant') {
267→          conversationHistory.push({ role: msg.role, content: msg.content });
268→        }
269→      }
270→
271→      const assistantId = generateId();
272→      assistantIdRef.current = assistantId;
273→
274→      const userMsg: ChatMessage = {
275→        id: generateId(),
276→        role: 'user',
277→        content: newContent,
278→      };
279→      const assistantMsg: ChatMessage = {
280→        id: assistantId,
281→        role: 'assistant',
282→        content: '',
283→        toolCalls: [],
284→        isStreaming: true,
285→      };
286→
287→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
288→      setIsStreaming(true);
289→      textBufferRef.current = '';
290→      segmentsRef.current = [];
291→      currentTextRef.current = '';
292→
293→      const controller = new AbortController();
294→      abortRef.current = controller;
295→
296→      await runAgentEditLoop(
297→        newContent,
298→        conversationHistory,
299→        crypto.randomUUID(),
300→        {
301→          onTextChunk: (chunk) => {
302→            textBufferRef.current += chunk;
303→            if (!flushTimerRef.current) {
304→              flushTimerRef.current = setTimeout(() => {
305→                flushText();
306→                flushTimerRef.current = null;
307→              }, 50);
308→            }
309→          },
310→          onThinkingDone: () => {
311→            if (flushTimerRef.current) {
312→              clearTimeout(flushTimerRef.current);
313→              flushTimerRef.current = null;
314→            }
315→            flushText();
316→            if (currentTextRef.current.trim()) {
317→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
318→              currentTextRef.current = '';
319→            }
320→            setMessages((prev) =>
321→              prev.map((m) =>
322→                m.id === assistantId
323→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
324→                  : m
325→              )
326→            );
327→          },
328→          onToolCall: (pending: ToolCallResult) => {
329→            if (flushTimerRef.current) {
330→              clearTimeout(flushTimerRef.current);
331→              flushTimerRef.current = null;
332→            }
333→            flushText();
334→            if (currentTextRef.current.trim()) {
335→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
336→              currentTextRef.current = '';
337→            }
338→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
339→            setMessages((prev) =>
340→              prev.map((m) =>
341→                m.id === assistantId
342→                  ? { ...m, segments: [...segmentsRef.current] }
343→                  : m
344→              )
345→            );
346→          },
347→          onToolResult: (result: ToolCallResult) => {
348→            const pendingIdx = segmentsRef.current.findIndex(
349→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
350→            );
351→            if (pendingIdx !== -1) {
352→              const pending = segmentsRef.current[pendingIdx].toolResult!;
353→              segmentsRef.current[pendingIdx] = {
354→                type: 'tool',
355→                toolResult: {
356→                  ...pending,
357→                  ...result,
358→                  sql: result.sql || pending.sql,
359→                  toolName: result.toolName || pending.toolName,
360→                  command: result.command || pending.command,
361→                  toolInput: result.toolInput || pending.toolInput,
362→                },
363→              };
364→            } else {
365→              segmentsRef.current.push({ type: 'tool', toolResult: result });
366→            }
367→            setMessages((prev) =>
368→              prev.map((m) =>
369→                m.id === assistantId
370→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
371→                  : m
372→              )
373→            );
374→            refreshTables();
375→          },
376→          onSubagentStart: (data) => {
377→            if (flushTimerRef.current) {
378→              clearTimeout(flushTimerRef.current);
379→              flushTimerRef.current = null;
380→            }
381→            flushText();
382→            if (currentTextRef.current.trim()) {
383→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
384→              currentTextRef.current = '';
385→            }
386→            segmentsRef.current.push({
387→              type: 'subagent_start',
388→              subagentId: data.id,
389→              subagentName: data.name,
390→              text: data.prompt,
391→            });
392→            setMessages((prev) =>
393→              prev.map((m) =>
394→                m.id === assistantId
395→                  ? { ...m, segments: [...segmentsRef.current] }
396→                  : m
397→              )
398→            );
399→          },
400→          onSubagentEnd: (data) => {
401→            segmentsRef.current.push({
402→              type: 'subagent_end',
403→              subagentId: data.id,
404→              subagentName: data.name,
405→              chart_spec: data.chart_spec,
406→              text: data.result,
407→            });
408→            setMessages((prev) =>
409→              prev.map((m) =>
410→                m.id === assistantId
411→                  ? { ...m, segments: [...segmentsRef.current] }
412→                  : m
413→              )
414→            );
415→          },
416→          onDone: (newSessionId) => {
417→            if (newSessionId) sessionIdRef.current = newSessionId;
418→            if (flushTimerRef.current) {
419→              clearTimeout(flushTimerRef.current);
420→              flushTimerRef.current = null;
421→            }
422→            flushText();
423→            if (currentTextRef.current.trim()) {
424→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
425→              currentTextRef.current = '';
426→            }
427→            setMessages((prev) =>
428→              prev.map((m) =>
429→                m.id === assistantId
430→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
431→                  : m
432→              )
433→            );
434→            setIsStreaming(false);
435→            abortRef.current = null;
436→          },
437→          onError: (error) => {
438→            if (flushTimerRef.current) {
439→              clearTimeout(flushTimerRef.current);
440→              flushTimerRef.current = null;
441→            }
442→            flushText();
443→            setMessages((prev) =>
444→              prev.map((m) =>
445→                m.id === assistantId
446→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
447→                  : m
448→              )
449→            );
450→            setIsStreaming(false);
451→            abortRef.current = null;
452→          },
453→        },
454→        controller.signal,
455→        userSessionId,
456→      );
457→    },
458→    [isStreaming, messages, flushText, refreshTables, userSessionId]
459→  );
460→
461→  const deleteMessage = useCallback(
462→    (messageIndex: number) => {
463→      if (isStreaming) return;
464→
465→      // Store remaining messages as history for Langfuse context on next send
466→      setMessages((prev) => {
467→        const remaining = prev.slice(0, messageIndex);
468→        pendingHistoryRef.current = remaining
469→          .filter((m) => m.role === 'user' || m.role === 'assistant')
470→          .map((m) => ({ role: m.role, content: m.content }));
471→        return remaining;
472→      });
473→
474→      // Clear session so next message starts fresh
475→      sessionIdRef.current = null;
476→    },
477→    [isStreaming]
478→  );
479→
480→  const clearMessages = useCallback(() => {
481→    if (abortRef.current) {
482→      abortRef.current.abort();
483→    }
484→    setMessages([]);
485→    setIsStreaming(false);
486→    sessionIdRef.current = null;
487→    pendingHistoryRef.current = null;
488→  }, []);
489→
490→  return (
491→    <AgentContext.Provider
492→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages }}
493→    >
494→      {children}
495→    </AgentContext.Provider>
496→  );
497→}
