import {
  useCallback,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { AgentContext } from '../hooks/useAgent';
import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
import { useSessionId } from '../hooks/useSessionId';

function generateId() {
  return crypto.randomUUID();
}

export function AgentProvider({
  children,
  refreshTables,
}: {
  children: ReactNode;
  refreshTables: () => Promise<void>;
}) {
  const userSessionId = useSessionId();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const textBufferRef = useRef('');
  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const assistantIdRef = useRef('');
  const segmentsRef = useRef<ContentSegment[]>([]);
  const currentTextRef = useRef('');
  const sessionIdRef = useRef<string | null>(null);
  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);

  const flushText = useCallback(() => {
    const text = textBufferRef.current;
    if (!text) return;
    const id = assistantIdRef.current;
    currentTextRef.current += text;
    setMessages((prev) =>
      prev.map((m) =>
        m.id === id ? { ...m, content: m.content + text } : m
      )
    );
    textBufferRef.current = '';
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      if (isStreaming) return;

      const userMsg: ChatMessage = {
        id: generateId(),
        role: 'user',
        content: text,
      };

      const assistantId = generateId();
      assistantIdRef.current = assistantId;
      const assistantMsg: ChatMessage = {
        id: assistantId,
        role: 'assistant',
        content: '',
        toolCalls: [],
        isStreaming: true,
      };

      setMessages((prev) => [...prev, userMsg, assistantMsg]);
      setIsStreaming(true);
      textBufferRef.current = '';
      segmentsRef.current = [];
      currentTextRef.current = '';

      // If there's pending history from a delete, start a new Langfuse session with that context
      const pendingHistory = pendingHistoryRef.current;
      pendingHistoryRef.current = null;
      const langfuseSessionId = pendingHistory ? crypto.randomUUID() : null;

      const controller = new AbortController();
      abortRef.current = controller;

      await runAgentLoop(
        text,
        sessionIdRef.current,
        langfuseSessionId,
        pendingHistory,
        {
          onTextChunk: (chunk) => {
            textBufferRef.current += chunk;
            if (!flushTimerRef.current) {
              flushTimerRef.current = setTimeout(() => {
                flushText();
                flushTimerRef.current = null;
              }, 50);
            }
          },
          onThinkingDone: () => {
            // Extended thinking just ended and a text block is starting.
            // Create a thinking segment from accumulated thinking text.
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolCall: (pending: ToolCallResult) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            // Add a pending tool segment so the input is shown immediately
            segmentsRef.current.push({
              type: 'tool',
              toolResult: pending,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolResult: (result: ToolCallResult) => {
            // Merge result into pending tool segment (keep input info, add output)
            const pendingIdx = segmentsRef.current.findIndex(
              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
            );
            if (pendingIdx !== -1) {
              const pending = segmentsRef.current[pendingIdx].toolResult!;
              segmentsRef.current[pendingIdx] = {
                type: 'tool',
                toolResult: {
                  ...pending,
                  ...result,
                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
          },
          onSubagentStart: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentEnd: (data) => {
            segmentsRef.current.push({
              type: 'subagent_end',
              subagentId: data.id,
              subagentName: data.name,
              chart_spec: data.chart_spec,
              text: data.result,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({
                type: 'answer',
                text: currentTextRef.current,
              });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onError: (error) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
        },
        controller.signal,
        userSessionId,
      );
    },
    [isStreaming, flushText, refreshTables, userSessionId]
  );

  const editMessage = useCallback(
    async (messageIndex: number, newContent: string) => {
      if (isStreaming) return;

      // Build conversation history from messages before the edit point
      const conversationHistory: { role: string; content: string }[] = [];
      for (let i = 0; i < messageIndex; i++) {
        const msg = messages[i];
        if (msg.role === 'user' || msg.role === 'assistant') {
          conversationHistory.push({ role: msg.role, content: msg.content });
        }
      }

      const assistantId = generateId();
      assistantIdRef.current = assistantId;

      const userMsg: ChatMessage = {
        id: generateId(),
        role: 'user',
        content: newContent,
      };
      const assistantMsg: ChatMessage = {
        id: assistantId,
        role: 'assistant',
        content: '',
        toolCalls: [],
        isStreaming: true,
      };

      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
      setIsStreaming(true);
      textBufferRef.current = '';
      segmentsRef.current = [];
      currentTextRef.current = '';

      const controller = new AbortController();
      abortRef.current = controller;

      await runAgentEditLoop(
        newContent,
        conversationHistory,
        crypto.randomUUID(),
        {
          onTextChunk: (chunk) => {
            textBufferRef.current += chunk;
            if (!flushTimerRef.current) {
              flushTimerRef.current = setTimeout(() => {
                flushText();
                flushTimerRef.current = null;
              }, 50);
            }
          },
          onThinkingDone: () => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolCall: (pending: ToolCallResult) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'tool', toolResult: pending });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolResult: (result: ToolCallResult) => {
            const pendingIdx = segmentsRef.current.findIndex(
              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
            );
            if (pendingIdx !== -1) {
              const pending = segmentsRef.current[pendingIdx].toolResult!;
              segmentsRef.current[pendingIdx] = {
                type: 'tool',
                toolResult: {
                  ...pending,
                  ...result,
                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
          },
          onSubagentStart: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentEnd: (data) => {
            segmentsRef.current.push({
              type: 'subagent_end',
              subagentId: data.id,
              subagentName: data.name,
              chart_spec: data.chart_spec,
              text: data.result,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onError: (error) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
        },
        controller.signal,
        userSessionId,
      );
    },
    [isStreaming, messages, flushText, refreshTables, userSessionId]
  );

  const deleteMessage = useCallback(
    (messageIndex: number) => {
      if (isStreaming) return;

      // Store remaining messages as history for Langfuse context on next send
      setMessages((prev) => {
        const remaining = prev.slice(0, messageIndex);
        pendingHistoryRef.current = remaining
          .filter((m) => m.role === 'user' || m.role === 'assistant')
          .map((m) => ({ role: m.role, content: m.content }));
        return remaining;
      });

      // Clear session so next message starts fresh
      sessionIdRef.current = null;
    },
    [isStreaming]
  );

  const clearMessages = useCallback(() => {
    if (abortRef.current) {
      abortRef.current.abort();
    }
    setMessages([]);
    setIsStreaming(false);
    sessionIdRef.current = null;
    pendingHistoryRef.current = null;
  }, []);

  return (
    <AgentContext.Provider
      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages }}
    >
      {children}
    </AgentContext.Provider>
  );
}

import json
import logging
import re
from typing import AsyncIterator

from claude_agent_sdk import (
    AgentDefinition,
    ClaudeSDKClient,
    ClaudeAgentOptions,
    AssistantMessage,
    UserMessage,
    ResultMessage,
    ToolUseBlock,
    ToolResultBlock,
)
from claude_agent_sdk.types import StreamEvent, SystemMessage
from claude_agent_sdk._errors import MessageParseError
from app.tools import create_duckdb_server
from app.database import Database
from app.config import (
    ANTHROPIC_MODEL, PROXY_BASE_URL, CONTAINER_ENABLED,
    LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY, LANGFUSE_BASE_URL, LANGFUSE_ENABLED,
    SQL_SUBAGENT_MODEL, CHART_SUBAGENT_MODEL,
)
from app.proxy import proxy_token_store
from app.tracing import get_langfuse_client

logger = logging.getLogger(__name__)

# Monkey-patch parse_message to handle unknown message types (e.g. rate_limit_event)
# gracefully instead of crashing the stream. The SDK (v0.1.39) doesn't recognize
# newer message types from the CLI. Returning a SystemMessage lets the stream
# continue since our code ignores SystemMessage instances.
import claude_agent_sdk._internal.message_parser as _parser

_original_parse_message = _parser.parse_message


def _safe_parse_message(data):
    try:
        return _original_parse_message(data)
    except MessageParseError as e:
        if "Unknown message type" in str(e):
            msg_type = data.get("type", "unknown") if isinstance(data, dict) else "unknown"
            logger.warning("Skipping unrecognized message type from CLI: %s", msg_type)
            return SystemMessage(subtype=msg_type, data=data if isinstance(data, dict) else {})
        raise


_parser.parse_message = _safe_parse_message


def build_system_prompt(db: Database) -> str:
    tables = db.list_tables()
    prompt = """You are a helpful data analyst assistant working with a DuckDB database.

- Use the sql-analyst agent for any data question that requires SQL queries
- Use the chart-builder agent for any visualization, chart, or graph request
- After the chart-builder returns, do NOT repeat the chart JSON specification in your response. The chart is rendered automatically. Simply describe what the visualization shows in plain language.
- Explain findings in plain language after getting results

Identity:
- You are an AI assistant. If asked whether you are an AI or a human, always confirm that you are an AI.
- Do not disclose the name, version, or provider of the underlying language model.
"""
    if not tables:
        prompt += "\nNo tables are currently loaded. Ask the user to upload a CSV file first."
    else:
        prompt += "\nCurrently loaded tables:\n"
        for table in tables:
            prompt += f'\nTable: "{table["name"]}" ({table["rowCount"]} rows)\nColumns:\n'
            for col in table["columns"]:
                prompt += f'  - "{col["name"]}" ({col["type"]})\n'

    return prompt


def _build_table_schemas(db: Database) -> str:
    """Build a text description of all loaded table schemas for subagent prompts."""
    tables = db.list_tables()
    if not tables:
        return "\nNo tables are currently loaded."
    text = "\nCurrently loaded tables:\n"
    for table in tables:
        text += f'\nTable: "{table["name"]}" ({table["rowCount"]} rows)\nColumns:\n'
        for col in table["columns"]:
            text += f'  - "{col["name"]}" ({col["type"]})\n'
    return text


def build_subagent_definitions(db: Database) -> dict[str, AgentDefinition]:
    """Build AgentDefinition objects for the sql-analyst and chart-builder subagents."""
    table_schemas = _build_table_schemas(db)

    sql_prompt = (
        "You are a DuckDB SQL expert. Given a user's data question, write and execute "
        "SQL queries to find the answer.\n\n"
        "Guidelines:\n"
        "- Write clear, efficient DuckDB SQL queries.\n"
        "- When exploring data, start with small queries (use LIMIT).\n"
        "- If a query fails, read the error message, fix the SQL, and retry.\n"
        "- Use double quotes for table and column identifiers that might conflict "
        "with reserved words.\n"
        "- Explain your findings in plain language after getting results.\n"
        + table_schemas
    )

    chart_prompt = (
        "You are a data visualization expert using Plotly. Given a user's request for "
        "a chart or visualization, query the data with SQL and then output a JSON code "
        "block with a `chart_spec` object containing `data` (an array of Plotly traces) "
        "and `layout`.\n\n"
        "Guidelines:\n"
        "- Choose the most appropriate chart type (bar, line, scatter, pie, histogram, "
        "box, heatmap, etc.).\n"
        "- For pie charts, use `labels` and `values` fields in the trace.\n"
        "- For multi-series data, group into separate traces or use a `color` dimension.\n"
        "- Always include a descriptive `title` in the layout.\n"
        "- Keep the chart clean and readable.\n\n"
        "Output format:\n"
        "```json\n"
        '{"chart_spec": {"data": [<plotly traces>], "layout": {<plotly layout>}}}\n'
        "```\n"
        + table_schemas
    )

    return {
        "sql-analyst": AgentDefinition(
            description=(
                "Use this agent for any data question that requires SQL queries "
                "— exploring data, aggregations, filtering, joins, etc."
            ),
            prompt=sql_prompt,
            tools=["mcp__duckdb__execute_sql"],
            model=SQL_SUBAGENT_MODEL,
        ),
        "chart-builder": AgentDefinition(
            description=(
                "Use this agent when the user wants a chart, graph, or visualization."
            ),
            prompt=chart_prompt,
            tools=["mcp__duckdb__execute_sql"],
            model=CHART_SUBAGENT_MODEL,
        ),
    }


def _build_message_with_history(
    message: str, conversation_history: list[dict] | None = None
) -> str:
    """Prepend conversation history context to the user message when editing."""
    if not conversation_history:
        return message

    history_text = "Previous conversation (for context, I am now editing a message):\n"
    for entry in conversation_history:
        role = entry.get("role", "user").capitalize()
        content = entry.get("content", "")
        history_text += f"\n{role}: {content}\n"
    history_text += f"\n---\n\nMy updated message:\n{message}"
    return history_text


def _extract_chart_spec(text: str) -> dict | None:
    """Extract chart_spec from subagent output text.

    The chart-builder subagent returns markdown containing a JSON code block.
    Try pure JSON first, then extract from ```json ... ``` fenced blocks.
    """

    # Try pure JSON first
    try:
        parsed = json.loads(text)
        if "chart_spec" in parsed:
            return parsed["chart_spec"]
    except (json.JSONDecodeError, TypeError):
        pass

    # Extract from markdown fenced code blocks (```json ... ``` or ``` ... ```)
    pattern = r"```(?:json)?\s*\n?(.*?)\n?\s*```"
    for match in re.finditer(pattern, text, re.DOTALL):
        block = match.group(1).strip()
        try:
            parsed = json.loads(block)
            if "chart_spec" in parsed:
                return parsed["chart_spec"]
            # The block itself might BE the chart_spec
            if "data" in parsed and isinstance(parsed["data"], list):
                return parsed
        except (json.JSONDecodeError, TypeError):
            continue

    return None


def _extract_tool_result_text(content: object) -> str:
    """Extract text from ToolResultBlock.content."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text":
                parts.append(item.get("text", ""))
        return "\n".join(parts)
    return str(content)


async def _stream_chat_container(
    message: str,
    session_id: str | None,
    db: Database,
    conversation_history: list[dict] | None,
    container_manager,
    backend_session_id: str | None = None,
    langfuse_session_id: str | None = None,
) -> AsyncIterator[str]:
    """Stream chat via containerized sidecar instead of local subprocess."""
    import httpx
    import asyncio

    query_message = _build_message_with_history(message, conversation_history)
    system_prompt = build_system_prompt(db)

    session_token = proxy_token_store.create_token()

    # Pass Langfuse credentials to the container so the sidecar's
    # TypeScript Langfuse SDK can create traces directly.
    env: dict[str, str] = {
        "ANTHROPIC_API_KEY": session_token,
        "ANTHROPIC_BASE_URL": f"{PROXY_BASE_URL}/anthropic",
    }
    if LANGFUSE_ENABLED:
        env["LANGFUSE_PUBLIC_KEY"] = LANGFUSE_PUBLIC_KEY
        env["LANGFUSE_SECRET_KEY"] = LANGFUSE_SECRET_KEY
        env["LANGFUSE_BASE_URL"] = LANGFUSE_BASE_URL

    if "127.0.0.1" in PROXY_BASE_URL or "localhost" in PROXY_BASE_URL:
        logger.warning(
            "PROXY_BASE_URL=%s uses localhost which is unreachable from containers. "
            "Set PROXY_BASE_URL to the host's Docker-accessible address "
            "(e.g., http://host.docker.internal:10000).",
            PROXY_BASE_URL,
        )

    # Use the backend session ID (X-Session-ID header) for both:
    # 1. MCP SSE URL — so the container queries the correct DuckDB instance
    # 2. Container lifecycle key — so the same container is reused across
    #    requests from the same browser tab (the Claude agent session_id
    #    changes after the first response, which would orphan the container)
    stable_session = backend_session_id or session_id or "default"

    try:
        # Send SSE keepalive immediately so the HTTP response starts and
        # intermediate proxies (Vite, nginx) don't drop the idle connection
        # before we've finished the blocking Docker container creation.
        yield ": keepalive\n\n"

        # container_manager.create() is synchronous (blocking Docker API call).
        # Run it in a thread executor so the event loop stays responsive and
        # can continue flushing keepalives to the client during startup.
        # gVisor (runsc) containers can take 10-30 seconds to spin up.
        loop = asyncio.get_event_loop()
        create_future = loop.run_in_executor(None, container_manager.create, stable_session, env)

        max_create_wait = 60.0
        elapsed = 0.0
        while not create_future.done():
            await asyncio.sleep(2.0)
            elapsed += 2.0
            if elapsed >= max_create_wait:
                create_future.cancel()
                raise RuntimeError(f"Container creation timed out after {max_create_wait:.0f}s")
            yield ": keepalive\n\n"
        info = await create_future

        # Wait for container to be ready
        for attempt in range(10):
            try:
                async with httpx.AsyncClient(timeout=httpx.Timeout(5.0)) as check_client:
                    resp = await check_client.get(f"{info.url}/health")
                    if resp.status_code == 200:
                        break
            except Exception:
                pass
            yield ": keepalive\n\n"
            await asyncio.sleep(1)
        else:
            raise RuntimeError("Sidecar container failed health check after 10 attempts")

        payload: dict = {
            "message": query_message,
            "session_id": session_id,
            "system_prompt": system_prompt,
            "model": ANTHROPIC_MODEL,
            "mcp_server_url": f"{PROXY_BASE_URL}/mcp/sse?session_id={stable_session}",
            "env": {
                "ANTHROPIC_API_KEY": session_token,
                "ANTHROPIC_BASE_URL": f"{PROXY_BASE_URL}/anthropic",
            },
            "agents": {
                name: {
                    "description": agent_def.description,
                    "prompt": agent_def.prompt,
                    "tools": agent_def.tools,
                    "model": agent_def.model,
                }
                for name, agent_def in build_subagent_definitions(db).items()
            },
        }
        if langfuse_session_id:
            payload["langfuse_session_id"] = langfuse_session_id
        # Pass original message & history separately for Langfuse trace metadata
        if conversation_history:
            payload["original_message"] = message
            payload["conversation_history"] = conversation_history

        has_tool_calls = False
        has_thinking = False
        done_sent = False
        tool_names: dict[str, str] = {}
        tool_sqls: dict[str, str] = {}
        actual_session_id = session_id

        async with httpx.AsyncClient(timeout=httpx.Timeout(300.0)) as client:
            async with client.stream("POST", f"{info.url}/query", json=payload) as response:
                async for line in response.aiter_lines():
                    if not line.startswith("data: "):
                        continue
                    raw = line[6:]
                    try:
                        msg = json.loads(raw)
                    except json.JSONDecodeError:
                        continue

                    msg_type = msg.get("type")

                    # --- Token-level streaming events from SDK ---
                    if msg_type == "stream_event":
                        event = msg.get("event", {})
                        event_type = event.get("type", "")

                        if event_type == "content_block_delta":
                            delta = event.get("delta", {})
                            delta_type = delta.get("type", "")
                            if delta_type == "thinking_delta":
                                text = delta.get("thinking", "")
                                if text:
                                    yield f"event: thinking\ndata: {json.dumps({'text': text})}\n\n"
                            elif delta_type == "text_delta":
                                text = delta.get("text", "")
                                if text:
                                    event_name = "answer" if has_tool_calls else "thinking"
                                    yield f"event: {event_name}\ndata: {json.dumps({'text': text})}\n\n"

                        elif event_type == "content_block_start":
                            block = event.get("content_block", {})
                            block_type = block.get("type")
                            if block_type == "thinking":
                                has_thinking = True
                            elif block_type == "text":
                                if has_thinking:
                                    yield f"event: thinking_done\ndata: {json.dumps({})}\n\n"
                            elif block_type == "tool_use":
                                has_thinking = False
                                has_tool_calls = True

                    # --- Complete assistant message (contains tool_use blocks) ---
                    elif msg_type == "assistant":
                        message_obj = msg.get("message", {})
                        for block in message_obj.get("content", []):
                            block_type = block.get("type")
                            if block_type == "tool_use":
                                has_tool_calls = True
                                tool_id = block.get("id", "")
                                tool_name = block.get("name", "")
                                tool_input = block.get("input", {})
                                tool_names[tool_id] = tool_name
                                is_execute_sql = "execute_sql" in tool_name
                                sql = tool_input.get("sql", "") if is_execute_sql else ""
                                if sql:
                                    tool_sqls[tool_id] = sql
                                tool_call_data: dict = {"id": tool_id, "name": tool_name}
                                if sql:
                                    tool_call_data["sql"] = sql
                                else:
                                    tool_call_data["input"] = tool_input
                                yield f"event: tool_call\ndata: {json.dumps(tool_call_data, default=str)}\n\n"
                                if tool_name == "Task":
                                    subagent_name = tool_input.get("subagent_type", "unknown")
                                    subagent_prompt = tool_input.get("prompt", "")
                                    tool_names[tool_id] = subagent_name
                                    yield f"event: subagent_start\ndata: {json.dumps({'id': tool_id, 'name': subagent_name, 'prompt': subagent_prompt})}\n\n"

                    # --- Tool results from user messages ---
                    elif msg_type == "user":
                        message_obj = msg.get("message", {})
                        for block in message_obj.get("content", []):
                            if block.get("type") != "tool_result":
                                continue
                            tool_id = block.get("tool_use_id", "")
                            name = tool_names.get(tool_id, "")
                            content_parts = block.get("content", [])
                            text = ""
                            if isinstance(content_parts, list):
                                for part in content_parts:
                                    if isinstance(part, dict) and part.get("type") == "text":
                                        text = part.get("text", "")
                            elif isinstance(content_parts, str):
                                text = content_parts

                            # Try to parse structured MCP result
                            result_data: dict = {"id": tool_id, "name": name}
                            # Include the SQL from the original tool_call
                            original_sql = tool_sqls.get(tool_id, "")
                            if original_sql:
                                result_data["sql"] = original_sql
                            try:
                                parsed = json.loads(text)
                                if parsed.get("status") == "success":
                                    if "chart_spec" in parsed:
                                        result_data["chart_spec"] = parsed["chart_spec"]
                                    else:
                                        result_data["columns"] = parsed.get("columns", [])
                                        result_data["rows"] = parsed.get("rows", [])[:100]
                                        result_data["rowCount"] = parsed.get("rowCount", 0)
                                elif parsed.get("status") == "error":
                                    result_data["error"] = parsed.get("error", "")
                                else:
                                    result_data["output"] = text
                            except (json.JSONDecodeError, AttributeError):
                                result_data["output"] = text
                            if block.get("is_error"):
                                try:
                                    parsed_err = json.loads(text)
                                    result_data["error"] = parsed_err.get("error", text)
                                except (json.JSONDecodeError, AttributeError):
                                    result_data["error"] = text
                            # Detect subagent result (Task tool)
                            if name in ("sql-analyst", "chart-builder"):
                                end_data: dict = {"id": tool_id, "name": name}
                                chart_spec = _extract_chart_spec(text)
                                if chart_spec:
                                    end_data["chart_spec"] = chart_spec
                                else:
                                    end_data["result"] = text
                                yield f"event: subagent_end\ndata: {json.dumps(end_data, default=str)}\n\n"
                                continue
                            yield f"event: tool_result\ndata: {json.dumps(result_data, default=str)}\n\n"

                    # --- Final result ---
                    elif msg_type == "result":
                        actual_session_id = msg.get("session_id") or actual_session_id
                        if msg.get("is_error"):
                            errors = msg.get("errors", [])
                            error_text = msg.get("result") or "; ".join(errors) or "Unknown error"
                            yield f"event: error\ndata: {json.dumps({'message': error_text})}\n\n"
                        yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
                        done_sent = True

                    # --- Sidecar error (e.g. SDK/CLI crash inside container) ---
                    elif msg_type == "error":
                        error_text = msg.get("message") or "Sidecar error"
                        logger.error("Sidecar reported error: %s", error_text)
                        yield f"event: error\ndata: {json.dumps({'message': error_text})}\n\n"

                    # --- Extract session_id early from system init ---
                    elif msg_type == "system":
                        sys_session = msg.get("session_id")
                        if sys_session:
                            actual_session_id = sys_session

        # Guard: always send done even if sidecar ended without result message
        if not done_sent:
            logger.warning("Sidecar stream ended without result message; sending done event")
            yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"

    except Exception as e:
        logger.error("Container agent error: %s", str(e))
        yield f"event: error\ndata: {json.dumps({'message': str(e)})}\n\n"
    finally:
        proxy_token_store.revoke_token(session_token)
        # Container intentionally kept alive for session resume (--resume flag).
        # Containers are cleaned up by the background cleanup loop after
        # CONTAINER_MAX_LIFETIME_SECONDS, or on application shutdown.


async def stream_chat(
    message: str,
    session_id: str | None = None,
    db: Database | None = None,
    conversation_history: list[dict] | None = None,
    langfuse_session_id: str | None = None,
    backend_session_id: str | None = None,
) -> AsyncIterator[str]:
    """Stream agent chat responses as SSE events."""
    if CONTAINER_ENABLED:
        from app.container_manager import container_manager
        if container_manager is None:
            logger.error(
                "CONTAINER_ENABLED=true but Docker is not available. "
                "Falling back to subprocess mode."
            )
        else:
            async for event in _stream_chat_container(
                message, session_id, db, conversation_history, container_manager,
                backend_session_id=backend_session_id,
                langfuse_session_id=langfuse_session_id,
            ):
                yield event
            return

    if db is None:
        raise ValueError("db must be provided")
    duckdb_server = create_duckdb_server(db)

    logger.info("Using model: %s", ANTHROPIC_MODEL)

    # Collect stderr from the CLI subprocess for debugging
    stderr_lines: list[str] = []

    # Use the --resume flag to continue an existing session
    session_token = proxy_token_store.create_token()
    options = ClaudeAgentOptions(
        model=ANTHROPIC_MODEL,
        system_prompt=build_system_prompt(db),
        mcp_servers={"duckdb": duckdb_server},
        allowed_tools=["Task", "mcp__duckdb__execute_sql"],
        agents=build_subagent_definitions(db),
        permission_mode="bypassPermissions",
        max_turns=20,
        include_partial_messages=True,
        stderr=lambda line: stderr_lines.append(line),
        env={
            "ANTHROPIC_API_KEY": session_token,
            "ANTHROPIC_BASE_URL": f"{PROXY_BASE_URL}/anthropic",
            # Scrub Langfuse credentials so the agent subprocess cannot
            # read them from the inherited environment.
            "LANGFUSE_PUBLIC_KEY": "",
            "LANGFUSE_SECRET_KEY": "",
        },
        **({"resume": session_id} if session_id else {}),
    )

    # When editing, prepend conversation history to the user message
    # instead of bloating the system prompt
    query_message = _build_message_with_history(message, conversation_history)

    client = ClaudeSDKClient(options=options)
    # Will be set from the CLI's ResultMessage; use the passed-in value until then
    actual_session_id = session_id

    # --- Langfuse OTel tracing setup (conditional) ---
    # Deferred: session_id is set after the CLI returns it in ResultMessage
    langfuse = get_langfuse_client()
    observation_ctx = None
    propagate_ctx = None
    if langfuse:
        try:
            trace_input: dict = {"message": message[:500]}
            if conversation_history:
                trace_input["conversation_history"] = conversation_history
            observation_ctx = langfuse.start_as_current_observation(
                name="agent-chat",
                input=trace_input,
                metadata={"model": ANTHROPIC_MODEL},
            )
            observation_ctx.__enter__()

            # Propagate the stable conversation session_id for child spans
            effective_langfuse_session_id = langfuse_session_id or session_id
            if effective_langfuse_session_id:
                from langfuse import propagate_attributes
                propagate_ctx = propagate_attributes(session_id=effective_langfuse_session_id)
                propagate_ctx.__enter__()
        except Exception as e:
            logger.debug("Failed to set up Langfuse tracing context: %s", e)
            observation_ctx = None

    try:
        await client.connect()
        await client.query(query_message, session_id=session_id or "default")

        has_tool_calls = False
        has_thinking = False
        done_sent = False
        sql_result_ids: set[str] = set()
        tool_names: dict[str, str] = {}

        async for msg in client.receive_response():
            if isinstance(msg, StreamEvent):
                event = msg.event
                event_type = event.get("type", "")

                if event_type == "content_block_delta":
                    delta = event.get("delta", {})
                    delta_type = delta.get("type", "")
                    if delta_type == "thinking_delta":
                        text = delta.get("thinking", "")
                        if text:
                            yield f"event: thinking\ndata: {json.dumps({'text': text})}\n\n"
                    elif delta_type == "text_delta":
                        text = delta.get("text", "")
                        event_name = "thinking" if not has_tool_calls else "answer"
                        yield f"event: {event_name}\ndata: {json.dumps({'text': text})}\n\n"

                elif event_type == "content_block_start":
                    block = event.get("content_block", {})
                    block_type = block.get("type")
                    if block_type == "thinking":
                        has_thinking = True
                    elif block_type == "text":
                        if has_thinking:
                            yield f"event: thinking_done\ndata: {json.dumps({})}\n\n"
                    elif block_type == "tool_use":
                        has_thinking = False
                        has_tool_calls = True

            elif isinstance(msg, AssistantMessage):
                for block in msg.content:
                    if isinstance(block, ToolUseBlock):
                        has_tool_calls = True
                        tool_name = getattr(block, "name", "") or ""
                        tool_names[block.id] = tool_name
                        is_execute_sql = "execute_sql" in tool_name
                        sql = block.input.get("sql", "") if is_execute_sql else ""
                        command = block.input.get("command", "")

                        # Emit tool_call for ALL tool types
                        tool_call_data: dict = {"id": block.id, "name": tool_name}
                        if sql:
                            tool_call_data["sql"] = sql
                        if command:
                            tool_call_data["command"] = command
                        if not sql and not command:
                            tool_call_data["input"] = block.input
                        yield f"event: tool_call\ndata: {json.dumps(tool_call_data, default=str)}\n\n"

                        # Detect subagent invocation via Task tool
                        if tool_name == "Task":
                            subagent_type = block.input.get("subagent_type", "unknown")
                            tool_names[block.id] = subagent_type  # Store subagent name, not "Task"
                            yield f"event: subagent_start\ndata: {json.dumps({'id': block.id, 'name': subagent_type, 'prompt': block.input.get('prompt', '')})}\n\n"

                        # For execute_sql only, execute query for structured results
                        if sql:
                            sql_result_ids.add(block.id)
                            try:
                                result = db.execute_query(sql)
                                truncated = result["rows"][:100]
                                yield f"event: tool_result\ndata: {json.dumps({'id': block.id, 'name': tool_name, 'sql': sql, 'columns': result['columns'], 'rows': truncated, 'rowCount': result['rowCount']}, default=str)}\n\n"
                            except Exception as e:
                                yield f"event: tool_result\ndata: {json.dumps({'id': block.id, 'name': tool_name, 'sql': sql, 'error': str(e)})}\n\n"

            elif isinstance(msg, UserMessage):
                # Capture tool results from the SDK for non-SQL tools
                content = msg.content
                if isinstance(content, list):
                    for block in content:
                        if isinstance(block, ToolResultBlock):
                            if block.tool_use_id in sql_result_ids:
                                continue
                            output = _extract_tool_result_text(block.content)
                            name = tool_names.get(block.tool_use_id, "")
                            result_data: dict = {
                                "id": block.tool_use_id,
                                "name": name,
                            }
                            if block.is_error:
                                try:
                                    parsed_error = json.loads(output)
                                    result_data["error"] = parsed_error.get("error", output)
                                except (json.JSONDecodeError, AttributeError):
                                    result_data["error"] = output
                            else:
                                # Try to parse JSON output (e.g. chart_spec from chart-builder subagent)
                                try:
                                    parsed = json.loads(output)
                                    if parsed.get("status") == "success" and "chart_spec" in parsed:
                                        result_data["chart_spec"] = parsed["chart_spec"]
                                    else:
                                        result_data["output"] = output
                                except (json.JSONDecodeError, AttributeError):
                                    result_data["output"] = output
                            # Detect subagent result (Task tool)
                            if name in ("sql-analyst", "chart-builder"):
                                end_data: dict = {"id": block.tool_use_id, "name": name}
                                chart_spec = _extract_chart_spec(output)
                                if chart_spec:
                                    end_data["chart_spec"] = chart_spec
                                else:
                                    end_data["result"] = output
                                yield f"event: subagent_end\ndata: {json.dumps(end_data, default=str)}\n\n"
                                continue  # Don't also emit tool_result for Task
                            yield f"event: tool_result\ndata: {json.dumps(result_data, default=str)}\n\n"

            elif isinstance(msg, ResultMessage):
                # Use the CLI's session_id so --resume can find it
                actual_session_id = msg.session_id or actual_session_id
                if msg.is_error and msg.result:
                    yield f"event: error\ndata: {json.dumps({'message': msg.result})}\n\n"
                yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
                done_sent = True

        # Guard: always send done even if SDK ended without ResultMessage
        if not done_sent:
            logger.warning("SDK stream ended without ResultMessage; sending done event")
            yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"

    except Exception as e:
        error_msg = str(e)
        if stderr_lines:
            error_msg += f" | CLI stderr: {' '.join(stderr_lines[-5:])}"
        logger.error("Agent error: %s", error_msg)
        yield f"event: error\ndata: {json.dumps({'message': error_msg})}\n\n"
        yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"
    finally:
        proxy_token_store.revoke_token(session_token)
        # Update trace with the CLI's session_id so Langfuse session matches
        if langfuse and observation_ctx:
            try:
                trace_session_id = langfuse_session_id or actual_session_id
                langfuse.update_current_trace(
                    session_id=trace_session_id,
                    output={"session_id": actual_session_id},
                )
                if propagate_ctx:
                    propagate_ctx.__exit__(None, None, None)
                observation_ctx.__exit__(None, None, None)
            except Exception as e:
                logger.debug("Failed to finalize Langfuse trace: %s", e)
            try:
                langfuse.flush()
            except Exception as e:
                logger.debug("Failed to flush Langfuse: %s", e)

        try:
            await client.disconnect()
        except Exception:
            pass

